    var normalizedKey = NormalizeKey(normalized).replace(/[^a-z0-9]/g, '');
    if (normalizedKey === 'none' || normalizedKey === 'null' || normalizedKey === 'undefined' || normalized === '-' || normalized === '[]') return null;
